window.SAOMD_STORIES[410401301]={"id":410401301,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410401301:1:1","speaker":"Cloaked Cait Sith","text":"Curses!","pose":20370107,"background":"bg_event_dungeon_sao","item":"","illustration":"","speaker_zh":"披风猫妖","text_zh":"诅咒！"}]},{"id":2,"order":2,"actions":[{"uid":"410401301:2:1","speaker":"Alice","text":"Stop right there!!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"站住！！"},{"uid":"410401301:2:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":3,"order":3,"actions":[{"uid":"410401301:3:1","speaker":"Eugeo","text":"We've tracked him this far!\nWe won't let him get away!","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我们已经追踪到他了！我们不会让他跑掉的！"}]},{"id":4,"order":4,"actions":[{"uid":"410401301:4:1","speaker":"Kirito","text":"Yeah!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯！"},{"uid":"410401301:4:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":5,"order":5,"actions":[{"uid":"410401301:5:1","speaker":"Cloaked Cait Sith","text":"Hmph, they've forced my hand...","pose":20370107,"background":"","item":"","illustration":"","speaker_zh":"披风猫妖","text_zh":"哼，他们逼我动手了……"}]},{"id":6,"order":6,"actions":[{"uid":"410401301:6:1","speaker":"Cloaked Cait Sith","text":"","pose":20370107,"background":"","item":"","illustration":"","speaker_zh":"披风猫妖","text_zh":""}]},{"id":7,"order":7,"actions":[{"uid":"410401301:7:1","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401301:7:2","speaker":"Asuna","text":"Huh?!\nLook, over there!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"啊？！看，那边！"}]},{"id":8,"order":8,"actions":[{"uid":"410401301:8:1","speaker":"Kirito","text":"Did he just summon a portal?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他刚才是召唤了传送门吗？！"}]},{"id":9,"order":9,"actions":[{"uid":"410401301:9:1","speaker":"Asuna","text":"Oh no! He's going to get away!","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哦不！他要逃走！"},{"uid":"410401301:9:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":10,"order":10,"actions":[{"uid":"410401301:10:1","speaker":"Cloaked Cait Sith","text":"Farewell, foolish fairies!","pose":20370105,"background":"bg_black","item":"","illustration":"","speaker_zh":"披风猫妖","text_zh":"再见了，愚蠢的妖精们！"}]},{"id":11,"order":11,"actions":[{"uid":"410401301:11:1","speaker":"Eugeo","text":"Wait!","pose":105302012,"background":"bg_event_dungeon_sao","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"等等！"},{"uid":"410401301:11:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":12,"order":12,"actions":[{"uid":"410401301:12:1","speaker":"Alice","text":"He fled into that black void!\nQuickly now, after him!","pose":105401012,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他逃进了那片黑色的虚空之中！现在快点，追上他！"}]},{"id":13,"order":13,"actions":[{"uid":"410401301:13:1","speaker":"Alice","text":"","pose":105401082,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":14,"order":14,"actions":[{"uid":"410401301:14:1","speaker":"Alice","text":"What?!","pose":105401082,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"什么？！"}]},{"id":15,"order":15,"actions":[{"uid":"410401301:15:1","speaker":"Kirito","text":"Alice!","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"爱丽丝！"},{"uid":"410401301:15:2","speaker":"Asuna","text":"","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":16,"order":16,"actions":[{"uid":"410401301:16:1","speaker":"Asuna","text":"Alice!","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"爱丽丝！"}]},{"id":17,"order":17,"actions":[{"uid":"410401301:17:1","speaker":"Alice","text":"I...can't enter this strange\nvoid?","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我……进不去这个奇怪的虚空？"},{"uid":"410401301:17:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":18,"order":18,"actions":[{"uid":"410401301:18:1","speaker":"Kirito","text":"...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."},{"uid":"410401301:18:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":19,"order":19,"actions":[{"uid":"410401301:19:1","speaker":"Kirito","text":"I don't think we can either.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我想我们也不能。"}]},{"id":20,"order":20,"actions":[{"uid":"410401301:20:1","speaker":"Eugeo","text":"Just what is this thing?","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"这到底是什么东西？"},{"uid":"410401301:20:2","speaker":"Alice","text":"","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":21,"order":21,"actions":[{"uid":"410401301:21:1","speaker":"Asuna","text":"It's a portal to\nanother place, Eugeo, but one\nthat only he can use.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"这是一个通往另一个地方的传送门，尤吉欧，但是只有他可以使用。"},{"uid":"410401301:21:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":22,"order":22,"actions":[{"uid":"410401301:22:1","speaker":"Kirito","text":"Apparently...\nDamn! And we were so close too!","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"看来……该死！我们也如此亲密！"}]},{"id":23,"order":23,"actions":[{"uid":"410401301:23:1","speaker":"Alice","text":"There's only two Divine Objects\nleft, and we know now that this\nCait Sith has one of them...","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"神器只剩下两件了，现在知道这个猫妖有一件了……"},{"uid":"410401301:23:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":24,"order":24,"actions":[{"uid":"410401301:24:1","speaker":"Alice","text":"I can't believe we let him\nescape us like that...","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我不敢相信我们让他就这样逃离了我们......"}]},{"id":25,"order":25,"actions":[{"uid":"410401301:25:1","speaker":"Eugeo","text":"Well, we tried... Huh?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯，我们尝试过……嗯？"}]},{"id":26,"order":26,"actions":[{"uid":"410401301:26:1","speaker":"Kirito","text":"What is it, Eugeo?","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么啊，尤吉欧？"},{"uid":"410401301:26:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":27,"order":27,"actions":[{"uid":"410401301:27:1","speaker":"Eugeo","text":"I can see something on the other\nside of that black void!","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我能看到那个黑色虚空的另一边有东西！"},{"uid":"410401301:27:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":28,"order":28,"actions":[{"uid":"410401301:28:1","speaker":"Asuna","text":"Hey, you're right!\nI think it's a town!","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嘿，你说得对！我认为这是一个城镇！"},{"uid":"410401301:28:2","speaker":"Kirito","text":"","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":29,"order":29,"actions":[{"uid":"410401301:29:1","speaker":"Kirito","text":"It definitely is a town, but it\ndoesn't look like any I've seen\nin Alfheim. It's very...Japanese.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"确实是个小镇，不过和我在阿尔普海姆里见过的不太一样。非常...日本。"}]},{"id":30,"order":30,"actions":[{"uid":"410401301:30:1","speaker":"Alice","text":"Japanese...?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"日语……？"},{"uid":"410401301:30:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":31,"order":31,"actions":[{"uid":"410401301:31:1","speaker":"Kirito","text":"Oh, uh...how do I explain this...?\nThe buildings look like they're\nfrom a different culture.","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哦，呃……这个该怎么解释呢……？这些建筑看起来像是来自不同的文化。"},{"uid":"410401301:31:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":32,"order":32,"actions":[{"uid":"410401301:32:1","speaker":"Asuna","text":"Maybe it's a special event area,\nlike what we had for Setsubun\nor Tanabata?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"也许这是一个特殊的活动区域，就像我们节分或七夕的活动区域？"}]},{"id":33,"order":33,"actions":[{"uid":"410401301:33:1","speaker":"Kirito","text":"But I haven't heard of any\nJapanese-themed events\nhappening in ALO now...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不过我还没听说ALO有什么日本主题的活动……"}]},{"id":34,"order":34,"actions":[{"uid":"410401301:34:1","speaker":"Kirito","text":"Hmm... No, it couldn't be...","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……不，不可能……"}]},{"id":35,"order":35,"actions":[{"uid":"410401301:35:1","speaker":"Asuna","text":"Couldn't be what, Kirito?","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不会是什么吧，桐人？"}]},{"id":36,"order":36,"actions":[{"uid":"410401301:36:1","speaker":"Kazuto","text":"Looks like we're all ready to go.","pose":10011305,"background":"bg_18_school","item":"","illustration":"","speaker_zh":"和人","text_zh":"看来我们都准备好了。"},{"uid":"410401301:36:2","speaker":"Asuna","text":"","pose":10021205,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":37,"order":37,"actions":[{"uid":"410401301:37:1","speaker":"Asuna","text":"I'm just glad we were able to\nformat Alice and Eugeo's data so\nthey could be converted over.","pose":10021205,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我很高兴我们能够格式化爱丽丝和尤吉欧的数据，以便它们可以转换。"}]},{"id":38,"order":38,"actions":[{"uid":"410401301:38:1","speaker":"Kazuto","text":"They were pretty suspicious about\nthe whole affair.","pose":100113042,"background":"","item":"","illustration":"","speaker_zh":"和人","text_zh":"他们对整件事非常怀疑。"}]},{"id":39,"order":39,"actions":[{"uid":"410401301:39:1","speaker":"Asuna","text":"And they were right to be. Not\nlike they would've believed us if\nwe said we're switching VRMMOs...","pose":100212042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他们是对的。如果我们说我们要切换 VRMMO，他们就不会相信我们了……"}]},{"id":40,"order":40,"actions":[{"uid":"410401301:40:1","speaker":"Kazuto","text":"Yeah, that wouldn't have gone\nover well...","pose":10011302,"background":"","item":"","illustration":"","speaker_zh":"和人","text_zh":"是啊，那样的话就不太顺利了……"}]},{"id":41,"order":41,"actions":[{"uid":"410401301:41:1","speaker":"Asuna","text":"But...did that Cait Sith really\nleave ALO and travel to another\nVRMMO? It seems impossible...","pose":10021202,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是……那个猫妖真的离开了ALO，前往了另一个VRMMO吗？看来不可能..."}]},{"id":42,"order":42,"actions":[{"uid":"410401301:42:1","speaker":"Kazuto","text":"Well, you saw it, right? That town\nwas definitely not from ALO. It\nwas a Japanese-themed VRMMO.","pose":10011307,"background":"","item":"","illustration":"","speaker_zh":"和人","text_zh":"嗯，你看到了，对吧？那个小镇绝对不是ALO的。这是一个日本主题的VRMMO。"}]},{"id":43,"order":43,"actions":[{"uid":"410401301:43:1","speaker":"Kazuto","text":"And it's got to be Asuka Empire.\nIt looked just like it.","pose":10011307,"background":"","item":"","illustration":"","speaker_zh":"和人","text_zh":"而且一定是飞鸟帝国。看起来就是这样。"}]},{"id":44,"order":44,"actions":[{"uid":"410401301:44:1","speaker":"Asuna","text":"Yuuki used to play Asuka Empire,\nright?","pose":10021202,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"优纪以前玩过飞鸟帝国吧？"}]},{"id":45,"order":45,"actions":[{"uid":"410401301:45:1","speaker":"Kazuto","text":"Yeah. It's connected to the Seed\nNexus, just like ALO, so data can\nbe transferred between the two.","pose":10011305,"background":"","item":"","illustration":"","speaker_zh":"和人","text_zh":"是啊。它与 Seed Nexus 相连，就像 ALO 一样，因此可以在两者之间传输数据。"}]},{"id":46,"order":46,"actions":[{"uid":"410401301:46:1","speaker":"Kazuto","text":"Player character data or NPC.\nEither way, the format's the same.","pose":10011305,"background":"","item":"","illustration":"","speaker_zh":"和人","text_zh":"玩家字符数据或 NPC。无论哪种方式，格式都是相同的。"}]},{"id":47,"order":47,"actions":[{"uid":"410401301:47:1","speaker":"Asuna","text":"I suppose that makes sense...","pose":10021209,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我觉得有道理……"}]},{"id":48,"order":48,"actions":[{"uid":"410401301:48:1","speaker":"Asuna","text":"Still, I'm amazed he thought to\njump VRMMOs. Cardinal really\nknows how to build an AI bad guy.","pose":10021209,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不过，我很惊讶他竟然想到去跳VRMMO。 卡迪纳尔真的知道如何打造一个人工智能坏人。"}]},{"id":49,"order":49,"actions":[{"uid":"410401301:49:1","speaker":"Kazuto","text":"But that's also his weakness.\nCardinal based that Cait Sith off\nAlice and Eugeo's data, right?","pose":10011307,"background":"","item":"","illustration":"","speaker_zh":"和人","text_zh":"但这也是他的弱点。 卡迪纳尔基于猫妖关闭爱丽丝和尤吉欧的数据，对吗？"}]},{"id":50,"order":50,"actions":[{"uid":"410401301:50:1","speaker":"Kazuto","text":"Well, their minds work just like\nours. In other words, AI or not,\nhe's got human limitations.","pose":10011307,"background":"","item":"","illustration":"","speaker_zh":"和人","text_zh":"嗯，他们的思维方式和我们一样。换句话说，无论是否是人工智能，他都有人类的局限性。"}]},{"id":51,"order":51,"actions":[{"uid":"410401301:51:1","speaker":"Kazuto","text":"We just need to predict his next\nmove, set a trap, and corner him.\nEasy as that.","pose":10011307,"background":"","item":"","illustration":"","speaker_zh":"和人","text_zh":"我们只需要预测他的下一步行动，设置陷阱，把他逼到墙角。就这么简单。"}]},{"id":52,"order":52,"actions":[{"uid":"410401301:52:1","speaker":"Asuna","text":"Yeah, you're right.\nWell, let's get to it!\nTo a new world!","pose":10021205,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊，你说得对。好吧，让我们开始吧！走向新世界！"}]},{"id":53,"order":53,"actions":[{"uid":"410401301:53:1","speaker":"Asuna","text":"I bet Alice and Eugeo can't wait\nfor us to get there and wake them\nup!","pose":10021204,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我敢打赌爱丽丝和尤吉欧已经等不及我们赶到并叫醒他们了！"}]},{"id":54,"order":54,"actions":[{"uid":"410401301:54:1","speaker":"Kazuto","text":"Yeah!","pose":10011304,"background":"","item":"","illustration":"","speaker_zh":"和人","text_zh":"嗯！"},{"uid":"410401301:54:2","speaker":"Asuna","text":"","pose":10021205,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":55,"order":55,"actions":[{"uid":"410401301:55:1","speaker":"Kirito","text":"...","pose":10012905,"background":"bg_white","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."}]},{"id":56,"order":56,"actions":[{"uid":"410401301:56:1","speaker":"Kirito","text":"The character conversion's almost\ncomplete...","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"角色转换快完成了……"}]},{"id":57,"order":57,"actions":[{"uid":"410401301:57:1","speaker":"Kirito","text":"Huh, what's this?","pose":10012903,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊，这是什么？"}]},{"id":58,"order":58,"actions":[{"uid":"410401301:58:1","speaker":"Kirito","text":"It wants me to pick a job?\nI guess I need to set a class\nbefore joining...","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"要我选工作？我想我需要在加入之前先设定一个班级..."}]},{"id":59,"order":59,"actions":[{"uid":"410401301:59:1","speaker":"Kirito","text":"Let me just check the class\ndescriptions... Hmm, let's go\nwith...this one.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我看一下班级描述吧……嗯，就……这个吧。"}]},{"id":60,"order":60,"actions":[{"uid":"410401301:60:1","speaker":"Alice","text":"Where...are we?","pose":10540108,"background":"bg_event_ayakashi_street","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们……在哪里？"},{"uid":"410401301:60:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":61,"order":61,"actions":[{"uid":"410401301:61:1","speaker":"Eugeo","text":"Wow! This world is so...bizarre!","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哇！这个世界就是这么……诡异！"}]},{"id":62,"order":62,"actions":[{"uid":"410401301:62:1","speaker":"Asuna","text":"Good morning, guys!\nHow are you feeling?","pose":10023004,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"大家早上好！你感觉怎么样？"},{"uid":"410401301:62:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":63,"order":63,"actions":[{"uid":"410401301:63:1","speaker":"Alice","text":"You are...Asuna? Your hair is a\ndifferent color, but...","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你是……亚丝娜？你的头发颜色不一样，但是..."},{"uid":"410401301:63:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":64,"order":64,"actions":[{"uid":"410401301:64:1","speaker":"Asuna","text":"Yup, it's me! I guess I just felt\nlike it was time for a change.\nMix it up a little, you know?","pose":100230042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的，是我！我想我只是觉得是时候做出改变了。稍微混合一下，你知道吗？"},{"uid":"410401301:64:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":65,"order":65,"actions":[{"uid":"410401301:65:1","speaker":"Alice","text":"Mix...what up?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"混……怎么了？"},{"uid":"410401301:65:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":66,"order":66,"actions":[{"uid":"410401301:66:1","speaker":"Asuna","text":"Well... I thought like changing my\nhair color might feel nice, that's\nall!","pose":100230022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯……我觉得换个发色可能会好点，仅此而已！"},{"uid":"410401301:66:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":67,"order":67,"actions":[{"uid":"410401301:67:1","speaker":"Eugeo","text":"Hmm, you both are wearing pretty\nunique new outfits.","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯，你们俩都穿着很独特的新衣服。"},{"uid":"410401301:67:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":68,"order":68,"actions":[{"uid":"410401301:68:1","speaker":"Kirito","text":"Hehe. I look pretty cool, right?","pose":10012904,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呵呵。我看起来很酷，对吧？"},{"uid":"410401301:68:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":69,"order":69,"actions":[{"uid":"410401301:69:1","speaker":"Alice","text":"Kirito, the change in your\nappearance is barely worth noting.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"桐人，你的外表变化几乎不值一提。"},{"uid":"410401301:69:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":70,"order":70,"actions":[{"uid":"410401301:70:1","speaker":"Kirito","text":"Ouch...","pose":10012906,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哎哟……"},{"uid":"410401301:70:2","speaker":"Asuna","text":"","pose":100230042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":71,"order":71,"actions":[{"uid":"410401301:71:1","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401301:71:2","speaker":"Alice","text":"We're done speaking of fashion. Is\nthis truly the world beyond that\nvoid? Are we no longer in Alfheim?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"时尚我们说完了。这真的是虚空之外的世界吗？我们已经不在阿尔普海姆了吗？"}]},{"id":72,"order":72,"actions":[{"uid":"410401301:72:1","speaker":"Kirito","text":"Y-Yeah, that's right. This world\nis completely separate from\nAlfheim.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是、是啊，是啊。这个世界与阿尔普海姆完全分开。"},{"uid":"410401301:72:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":73,"order":73,"actions":[{"uid":"410401301:73:1","speaker":"Kirito","text":"It has its own history and\nculture. That's why the people and\nbuildings look totally different.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"有自己的历史和文化。这就是为什么人和建筑物看起来完全不同。"}]},{"id":74,"order":74,"actions":[{"uid":"410401301:74:1","speaker":"Eugeo","text":"Well, I like it here! It seems\nlike a fun place! Can we go\nexplore now?","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯，我喜欢这里！看来是个好玩的地方啊！我们现在可以去探索吗？"},{"uid":"410401301:74:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":75,"order":75,"actions":[{"uid":"410401301:75:1","speaker":"Alice","text":"Eugeo, this is not a leisurely\nouting. We have a purpose here,\nor have you forgotten?","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧，这不是一次悠闲的郊游。我们来这里是有目的的，还是你忘记了？"}]},{"id":76,"order":76,"actions":[{"uid":"410401301:76:1","speaker":"Eugeo","text":"S-Sorry, Alice. I know...\nWe're here to find that\ncloaked Cait Sith...","pose":105302082,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"S-对不起，爱丽丝。我知道...我们来这里是为了找到那个隐形的猫妖..."}]},{"id":77,"order":77,"actions":[{"uid":"410401301:77:1","speaker":"Asuna","text":"About that...\nWhen he converted...","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"关于那个……他皈依的时候……"},{"uid":"410401301:77:2","speaker":"Kirito","text":"","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":78,"order":78,"actions":[{"uid":"410401301:78:1","speaker":"Asuna","text":"I mean, when he came to this\nworld, he may have changed\nhis appearance.","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我是说，他来到这个世界的时候，可能已经改变了外貌。"}]},{"id":79,"order":79,"actions":[{"uid":"410401301:79:1","speaker":"Eugeo","text":"He can do that?","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"他能做到吗？"},{"uid":"410401301:79:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":80,"order":80,"actions":[{"uid":"410401301:80:1","speaker":"Kirito","text":"Yeah, and it's likely he assumed\nthe clothes and form of a local\nto blend in.","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的，而且他很可能会穿上当地人的衣服和形状来融入。"},{"uid":"410401301:80:2","speaker":"Asuna","text":"","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":81,"order":81,"actions":[{"uid":"410401301:81:1","speaker":"Kirito","text":"Hmm... Maybe disguising himself\nwas one of the reasons why he\njumped worlds...","pose":10012902,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……也许伪装自己是他跳跃世界的原因之一……"}]},{"id":82,"order":82,"actions":[{"uid":"410401301:82:1","speaker":"Alice","text":"So he no longer appears to be a\nCait Sith?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"所以他看起来不再是猫妖了？"},{"uid":"410401301:82:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":83,"order":83,"actions":[{"uid":"410401301:83:1","speaker":"Kirito","text":"Exactly. Hey, I've got an idea.\nSince he's no longer a Cait Sith,\nlet's give him a new name.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"没错。嘿，我有一个主意。既然他不再是猫妖，我们就给他起个新名字吧。"},{"uid":"410401301:83:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":84,"order":84,"actions":[{"uid":"410401301:84:1","speaker":"Kirito","text":"Highly Intelligent Mob,\nor \"Hi-Mob\" for short.","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"高度智能暴民，简称“Hi-Mob”。"}]},{"id":85,"order":85,"actions":[{"uid":"410401301:85:1","speaker":"Eugeo","text":"Hi-Mob? What's that supposed\nto mean?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"Hi-Mob？那是什么意思？"},{"uid":"410401301:85:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":86,"order":86,"actions":[{"uid":"410401301:86:1","speaker":"Asuna","text":"It means \"a very smart enemy.\"\nSince we don't know what he looks\nlike anymore,","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"意思是“非常聪明的敌人”。因为我们已经不知道他长什么样子了"},{"uid":"410401301:86:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":87,"order":87,"actions":[{"uid":"410401301:87:1","speaker":"Asuna","text":"I guess that's a good enough way\nto refer to him for now.","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我想现在这样来称呼他已经足够了。"}]},{"id":88,"order":88,"actions":[{"uid":"410401301:88:1","speaker":"Alice","text":"Understood. From here on, we shall\ncall our enemy \"Hi-Mob.\"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"明白了。从现在开始，我们将称我们的敌人为“Hi-Mob”。"},{"uid":"410401301:88:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":89,"order":89,"actions":[{"uid":"410401301:89:1","speaker":"Kirito","text":"Great! Now, let's take a look\naround and see what this new\nworld's like!","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"太好了！现在，让我们环顾四周，看看这个新世界是什么样的！"},{"uid":"410401301:89:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":90,"order":90,"actions":[{"uid":"410401301:90:1","speaker":"Kirito","text":"Whoa! Samurai and Japanese\nmonsters are all just walking\naround town! So cool!","pose":10012908,"background":"bg_event_ayakashi_street","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哇哦！武士和日本怪物都在镇上闲逛！太酷了！"},{"uid":"410401301:90:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":91,"order":91,"actions":[{"uid":"410401301:91:1","speaker":"Asuna","text":"Yeah, it's like all the monsters\nand demons of Japanese folklore\nare everywhere here!","pose":10023011,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊，日本民间传说中的妖魔鬼怪都在这里了！"}]},{"id":92,"order":92,"actions":[{"uid":"410401301:92:1","speaker":"Alice","text":"You are not terrified by these\nfearsome apparitions, Asuna?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"亚丝娜，你不被这些可怕的幽灵吓到吗？"},{"uid":"410401301:92:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":93,"order":93,"actions":[{"uid":"410401301:93:1","speaker":"Asuna","text":"Not really. I can take these kinds\nof ghosts and goblins. It's the\nhorror stuff I can't deal with.","pose":100230042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不是。这种妖魔鬼怪我都能对付。这是我无法应对的恐怖事情。"},{"uid":"410401301:93:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":94,"order":94,"actions":[{"uid":"410401301:94:1","speaker":"Eugeo","text":"You know, looking around,\nthis place is pretty flashy.\nEverything's so...lively!","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你瞧，环顾四周，这地方相当浮华。一切都是那么……热闹！"},{"uid":"410401301:94:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":95,"order":95,"actions":[{"uid":"410401301:95:1","speaker":"Eugeo","text":"It's like a festival!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"就像过节一样！"}]},{"id":96,"order":96,"actions":[{"uid":"410401301:96:1","speaker":"Kirito","text":"Well, I don't think it's \"like\"\na festival, I think it IS a\nfestival!","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯，我不认为这“像”一个节日，我认为这是一个节日！"},{"uid":"410401301:96:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":97,"order":97,"actions":[{"uid":"410401301:97:1","speaker":"Kirito","text":"Asuka Empire's right in the middle\nof celebrating the New Year!","pose":10012904,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"飞鸟帝国正在庆祝新年！"}]},{"id":98,"order":98,"actions":[{"uid":"410401301:98:1","speaker":"Eugeo","text":"It's New Year's here?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"新年到了？"},{"uid":"410401301:98:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":99,"order":99,"actions":[{"uid":"410401301:99:1","speaker":"Asuna","text":"Yup! And they apparently celebrate\nit in style!","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊！他们显然很时尚地庆祝它！"},{"uid":"410401301:99:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":100,"order":100,"actions":[{"uid":"410401301:100:1","speaker":"Alice","text":"I see. That explains why they are\nall reveling so, but I find it a\nbit too loud for my tastes.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"原来如此。这解释了为什么他们都如此狂欢，但我发现这对我的口味来说有点太大声了。"},{"uid":"410401301:100:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":101,"order":101,"actions":[{"uid":"410401301:101:1","speaker":"Eugeo","text":"Well, I like it here. It's fun!\nBut I am a bit worried...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯，我喜欢这里。很有趣！但我有点担心..."}]},{"id":102,"order":102,"actions":[{"uid":"410401301:102:1","speaker":"Kirito","text":"About what?","pose":10012903,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"关于什么？"},{"uid":"410401301:102:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":103,"order":103,"actions":[{"uid":"410401301:103:1","speaker":"Eugeo","text":"All this commotion will make it\nnearly impossible to find our\nHi-Mob.","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"所有这些骚动将使我们几乎不可能找到我们的 Hi-Mob。"},{"uid":"410401301:103:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":104,"order":104,"actions":[{"uid":"410401301:104:1","speaker":"Kirito","text":"Good point...","pose":10012908,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"说得好……"},{"uid":"410401301:104:2","speaker":"Asuna","text":"","pose":10023011,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410401301:105:1","speaker":"Asuna","text":"Do you think that's why he came\nhere? To hide from us in all this\nchaos?","pose":10023011,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你认为这就是他来这里的原因吗？在这混乱之中躲避我们？"}]},{"id":106,"order":106,"actions":[{"uid":"410401301:106:1","speaker":"Kirito","text":"I wouldn't be surprised. He really\nthought of everything, huh?","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我不会感到惊讶。他还真是什么都想到了啊？"}]},{"id":107,"order":107,"actions":[{"uid":"410401301:107:1","speaker":"Kirito","text":"Converting let him change his\nappearance and lose us in this\nholiday crowd.","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"皈依让他改变了外表，让我们在这个节日的人群中消失了。"}]},{"id":108,"order":108,"actions":[{"uid":"410401301:108:1","speaker":"Kirito","text":"He's way smarter than we\nanticipated...","pose":10012902,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他比我们想象的聪明多了……"}]},{"id":109,"order":109,"actions":[{"uid":"410401301:109:1","speaker":"Asuna","text":"Well, I think we won't have to\nworry about any other deceptions\nor tricks.","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，我想我们不必担心任何其他的欺骗或伎俩。"}]},{"id":110,"order":110,"actions":[{"uid":"410401301:110:1","speaker":"Kirito","text":"Why do you say that, Asuna?","pose":10012903,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"为什么这么说呢，亚丝娜？"}]},{"id":111,"order":111,"actions":[{"uid":"410401301:111:1","speaker":"Asuna","text":"He came here so that he could hide\nin plain sight, right? Like a tree\nin the forest.","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他来这里就是为了躲在众目睽睽之下对吧？就像森林里的一棵树。"}]},{"id":112,"order":112,"actions":[{"uid":"410401301:112:1","speaker":"Asuna","text":"But I highly doubt he had the time\nto come up with an even sneakier\nor more ingenious plan.","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但我非常怀疑他有时间想出更狡猾或更巧妙的计划。"}]},{"id":113,"order":113,"actions":[{"uid":"410401301:113:1","speaker":"Asuna","text":"My guess is, he found the most\ncrowded place in town and is\nhiding out there.","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我的猜测是，他找到了镇上最拥挤的地方，并躲在那里。"}]},{"id":114,"order":114,"actions":[{"uid":"410401301:114:1","speaker":"Kirito","text":"Ahh, interesting theory!","pose":10012908,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊啊，有趣的理论！"}]},{"id":115,"order":115,"actions":[{"uid":"410401301:115:1","speaker":"Alice","text":"That detective seemed extremely\nunreliable. Do you really think we\ncan trust someone like that?","pose":10540102,"background":"bg_event_ayakashi_street","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那个侦探看起来很不靠谱啊。你真的认为我们可以信任这样的人吗？"},{"uid":"410401301:115:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":116,"order":116,"actions":[{"uid":"410401301:116:1","speaker":"Asuna","text":"The Mitsuba Detective Agency has\na good reputation, so I think so.","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"三叶侦探社的名声不错，所以我也这么认为。"},{"uid":"410401301:116:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":117,"order":117,"actions":[{"uid":"410401301:117:1","speaker":"Eugeo","text":"Well, we know that there's a big,\ntraditional game tournament going\non today in Ayakashi Alley.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯，我们知道今天在绫香巷有一场大型的传统游戏锦标赛。"},{"uid":"410401301:117:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":118,"order":118,"actions":[{"uid":"410401301:118:1","speaker":"Kirito","text":"Supposedly, it's karuta. That game\nis the most popular one here\nduring the New Year's season.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"据说是歌牌。该游戏是新年期间最受欢迎的游戏。"},{"uid":"410401301:118:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":119,"order":119,"actions":[{"uid":"410401301:119:1","speaker":"Alice","text":"What is this \"karuta\" you speak of?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你说的“歌牌”是什么？"},{"uid":"410401301:119:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":120,"order":120,"actions":[{"uid":"410401301:120:1","speaker":"Asuna","text":"It's a game you play with picture\ncards. It's sort of a tradition in\nJapan... I mean, the Asuka Empire.","pose":10023002,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"这是一个用图卡玩的游戏。这是日本的一种传统……我是说，飞鸟帝国。"},{"uid":"410401301:120:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":121,"order":121,"actions":[{"uid":"410401301:121:1","speaker":"Asuna","text":"The rules are pretty simple, so\nit's quite easy to pick up.","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"规则很简单，所以很容易上手。"}]},{"id":122,"order":122,"actions":[{"uid":"410401301:122:1","speaker":"Alice","text":"I have no desire to waste my time\nplaying this game.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我不想浪费时间玩这个游戏。"},{"uid":"410401301:122:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":123,"order":123,"actions":[{"uid":"410401301:123:1","speaker":"Kirito","text":"Well, hold on a sec. It might be\na good idea to join the karuta\ntournament.","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好的，请稍等。参加卡鲁塔锦标赛可能是个好主意。"},{"uid":"410401301:123:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":124,"order":124,"actions":[{"uid":"410401301:124:1","speaker":"Eugeo","text":"Why?","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"为什么？"},{"uid":"410401301:124:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":125,"order":125,"actions":[{"uid":"410401301:125:1","speaker":"Kirito","text":"I bet you our elusive enemy is\nin Ayakashi Alley. Either watching\nthe tournament,","pose":10012902,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我敢打赌，我们难以捉摸的敌人就在绫香巷里。无论是观看比赛，"},{"uid":"410401301:125:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":126,"order":126,"actions":[{"uid":"410401301:126:1","speaker":"Kirito","text":"or playing himself. What better\nplace for him to hide in plain\nsight than on stage?","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"或者扮演他自己。对于他来说，还有什么地方比舞台上更适合隐藏在众目睽睽之下呢？"}]},{"id":127,"order":127,"actions":[{"uid":"410401301:127:1","speaker":"Asuna","text":"Hmm, that kinda makes sense. We\nwouldn't expect him to be standing\nin the spotlight.","pose":10023007,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，有点道理。我们没想到他会站在聚光灯下。"}]},{"id":128,"order":128,"actions":[{"uid":"410401301:128:1","speaker":"Kirito","text":"Exactly. So we join the tournament\nand give each and every player a\nclose look over. Sound good?","pose":10012907,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"没错。因此，我们参加了比赛，并对每一个玩家进行仔细检查。听起来不错吗？"}]},{"id":129,"order":129,"actions":[{"uid":"410401301:129:1","speaker":"Alice","text":"Kirito... You have purposefully\nformulated a paper-thin excuse to\nplay this karuta game. Admit it.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"桐人...你故意为玩这个卡鲁塔游戏编造了一个薄弱的借口。承认吧。"},{"uid":"410401301:129:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":130,"order":130,"actions":[{"uid":"410401301:130:1","speaker":"Kirito","text":"N-No, not at all! Honest!","pose":100129082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不、不，一点也不！诚实的！"},{"uid":"410401301:130:2","speaker":"Asuna","text":"","pose":100230042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":131,"order":131,"actions":[{"uid":"410401301:131:1","speaker":"Eugeo","text":"Alice has a very good point.\nEvery time you go somewhere new,","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"爱丽丝说得很好。每次去一个新的地方，"},{"uid":"410401301:131:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":132,"order":132,"actions":[{"uid":"410401301:132:1","speaker":"Eugeo","text":"you just HAVE to try anything\nand everything. Especially games.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你必须尝试一切。尤其是游戏。"}]},{"id":133,"order":133,"actions":[{"uid":"410401301:133:1","speaker":"Kirito","text":"H-Hey, hold it! Priorities! I have\n'em! I know getting that Divine\nObject comes first!","pose":100129082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"喂、喂，坚持住！优先事项！我有它们！我知道得到那件神物是第一位的！"},{"uid":"410401301:133:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":134,"order":134,"actions":[{"uid":"410401301:134:1","speaker":"Asuna","text":"Hehe... You two have learned how\nto read Kirito pretty well. I'd say\nyou're on to something.","pose":10023004,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵……你们两个读桐人已经学得不错了。我想说你正在做某事。"}]},{"id":135,"order":135,"actions":[{"uid":"410401301:135:1","speaker":"Kirito","text":"Asuna, you too? Give me a break!","pose":100129022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"亚丝娜，你也是吗？让我休息一下吧！"}]},{"id":136,"order":136,"actions":[{"uid":"410401301:136:1","speaker":"Eugeo","text":"Ahaha!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"啊哈哈！"},{"uid":"410401301:136:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":137,"order":137,"actions":[{"uid":"410401301:137:1","speaker":"Alice","text":"...*snicker*","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"……*偷笑*"}]},{"id":138,"order":138,"actions":[{"uid":"410401301:138:1","speaker":"Asuna","text":"Oh my gosh! Alice just laughed!!","pose":10023011,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"天哪！ 爱丽丝只是笑了！！"},{"uid":"410401301:138:2","speaker":"Kirito","text":"","pose":10012903,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":139,"order":139,"actions":[{"uid":"410401301:139:1","speaker":"Alice","text":"I-I'm not laughing!\nIt was just a gasp...!","pose":105401011,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我、我没有笑！只是一声喘息……！"},{"uid":"410401301:139:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":140,"order":140,"actions":[{"uid":"410401301:140:1","speaker":"Alice","text":"N-Now come, we have important work\nto do! To Ayakashi Alley!","pose":105401071,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"来、来吧，我们还有重要的工作要做！到绫香胡同！"}]},{"id":141,"order":141,"actions":[{"uid":"410401301:141:1","speaker":"Kirito","text":"Yeah!","pose":10012904,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯！"},{"uid":"410401301:141:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":142,"order":142,"actions":[{"uid":"410401301:142:1","speaker":"Reciter","text":"Every time a dog goes on a\nstroll...","pose":2,"background":"bg_event_ayakashi_street","item":"","illustration":"","speaker_zh":"朗诵者","text_zh":"每次狗散步的时候..."},{"uid":"410401301:142:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401301:142:3","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":143,"order":143,"actions":[{"uid":"410401301:143:1","speaker":"Player","text":"Got it!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"知道了！"}]},{"id":144,"order":144,"actions":[{"uid":"410401301:144:1","speaker":"Kirito","text":"Ooh, nice!","pose":10012904,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哦，太好了！"}]},{"id":145,"order":145,"actions":[{"uid":"410401301:145:1","speaker":"Asuna","text":"I think that's a karuta corner\nfor kids.","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我觉得那是一个适合小孩子的歌牌角。"}]},{"id":146,"order":146,"actions":[{"uid":"410401301:146:1","speaker":"Reciter","text":"The days grow warmer, yet...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"朗诵者","text_zh":"天渐渐暖和了，但是……"}]},{"id":147,"order":147,"actions":[{"uid":"410401301:147:1","speaker":"Alice","text":"Wh-What speed!!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"什、什么速度！！"},{"uid":"410401301:147:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":148,"order":148,"actions":[{"uid":"410401301:148:1","speaker":"Eugeo","text":"They're really fast...\nTheir reaction speed might\neven beat Kirito's!","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"他们真快……反应速度甚至比桐人还要快！"}]},{"id":149,"order":149,"actions":[{"uid":"410401301:149:1","speaker":"Kirito","text":"That group over there is playing\nthe real deal: hyakunin isshu.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那边那个组合正在玩真正的游戏：百人一集。"},{"uid":"410401301:149:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":150,"order":150,"actions":[{"uid":"410401301:150:1","speaker":"Asuna","text":"The second they hear the first\nphrase, they leap forward and\nsnatch the right card...","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他们一听到第一句话，就向前跳去，抢走了正确的牌……"}]},{"id":151,"order":151,"actions":[{"uid":"410401301:151:1","speaker":"Asuna","text":"Each match is decided in the blink\nof an eye... These players are\nincredible!","pose":10023004,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"每一场比赛都在眨眼间决定胜局……这些玩家太不可思议了！"}]},{"id":152,"order":152,"actions":[{"uid":"410401301:152:1","speaker":"Alice","text":"I see what's going on.","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我知道怎么回事了。"},{"uid":"410401301:152:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":153,"order":153,"actions":[{"uid":"410401301:153:1","speaker":"Alice","text":"I think their speed is\nsomething we can learn.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我觉得他们的速度值得我们学习。"}]},{"id":154,"order":154,"actions":[{"uid":"410401301:154:1","speaker":"Kirito","text":"Well, we're not just here to\nwatch! Come on, guys! Let's\njoin the tournament!","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯，我们不只是来看的！来吧，伙计们！让我们一起参加锦标赛吧！"},{"uid":"410401301:154:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":155,"order":155,"actions":[{"uid":"410401301:155:1","speaker":"Eugeo","text":"You did teach us how to play, but\nthere's no way we can memorize all\nthose word combinations that fast!","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你确实教我们怎么玩，但我们不可能那么快记住所有这些单词组合！"},{"uid":"410401301:155:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":156,"order":156,"actions":[{"uid":"410401301:156:1","speaker":"Kirito","text":"True... But this is a multi-day\ntournament! Just learn as you\ngo, okay? You'll be fine.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"确实……但是这是一场多日比赛！边走边学，好吗？你会没事的。"},{"uid":"410401301:156:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":157,"order":157,"actions":[{"uid":"410401301:157:1","speaker":"Kirito","text":"I know how smart you guys are;\nyou'll figure it out quick and\nhave a lot of fun!","pose":10012904,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我知道你们有多聪明；你会很快明白并享受很多乐趣！"}]},{"id":158,"order":158,"actions":[{"uid":"410401301:158:1","speaker":"Alice","text":"Fun? I knew it. You're just here\nto fool around, Kirito.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"好玩吗？我就知道。你就是来搞笑的，桐人。"},{"uid":"410401301:158:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":159,"order":159,"actions":[{"uid":"410401301:159:1","speaker":"Eugeo","text":"It was so obvious.","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"太明显了。"}]},{"id":160,"order":160,"actions":[{"uid":"410401301:160:1","speaker":"Asuna","text":"Ahaha, yeah...","pose":100230042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"啊哈哈，是啊……"},{"uid":"410401301:160:2","speaker":"Kirito","text":"","pose":100129022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":161,"order":161,"actions":[{"uid":"410401301:161:1","speaker":"Kirito","text":"H-Hey, is that a practice area?\nLet's go check it out!","pose":100129032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"喂、喂，那是练习场吗？我们去看看吧！"}]},{"id":162,"order":162,"actions":[{"uid":"410401301:162:1","speaker":"Kirito","text":"It looks like they'll teach you\nall the basics of the game.","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"看来他们会教你所有游戏的基础知识。"},{"uid":"410401301:162:2","speaker":"Asuna","text":"","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":163,"order":163,"actions":[{"uid":"410401301:163:1","speaker":"Alice","text":"*sigh* Fine. But I do not think\nthat we'll find our quarry here.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"*叹气*好吧。但我不认为我们会在这里找到我们的猎物。"},{"uid":"410401301:163:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":164,"order":164,"actions":[{"uid":"410401301:164:1","speaker":"Alice","text":"Then again, it's better than\nhaving no plan, I suppose.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"话又说回来，我想这比没有计划要好。"}]},{"id":165,"order":165,"actions":[{"uid":"410401301:165:1","speaker":"Eugeo","text":"Yeah. It might not be the most\nefficient plan we've come up with,\nbut it's a start.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是啊。这可能不是我们提出的最有效的计划，但它是一个开始。"}]},{"id":166,"order":166,"actions":[{"uid":"410401301:166:1","speaker":"Asuna","text":"Great! Let's get playing!","pose":10023005,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"太好了！我们来玩吧！"},{"uid":"410401301:166:2","speaker":"Kirito","text":"","pose":10012905,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]}]};
